//! Standard library documentation pages (`/stdlib` and `/stdlib/{module}`).
//!
//! Renders the modules, operator/function signatures, doc comments, and
//! examples loaded from `AEVIA_STDLIB_DOCS_DIR` (`stdlib-docs.json` or
//! Markdown files generated by `aevia doc --stdlib`).

use aevia_registry_core::Lang;
use aevia_registry_core::vm::StdlibBook;
use aevia_registry_core::vm::StdlibItem;
use aevia_registry_core::vm::StdlibModule;
use aevia_registry_core::vm::Viewer;
use leptos::either::Either;
use leptos::prelude::AnyView;
use leptos::prelude::IntoAny;
use leptos::prelude::*;

use crate::Msg;
use crate::layout;
use crate::thousands;

const TITLE: Msg = Msg::new("standard library", "标准库");
const LEDE: Msg = Msg::new(
    "Built-in modules, operators, functions, dimensions, and physical units.",
    "内置模块、运算符、函数、量纲与物理单位。",
);
const NO_STDLIB: Msg = Msg::new(
    "Standard library documentation is not mounted on this deployment. Set \
     AEVIA_STDLIB_DOCS_DIR to the directory generated by `aevia doc --stdlib`.",
    "本次部署没有挂载标准库文档。请把 AEVIA_STDLIB_DOCS_DIR 指向 `aevia doc --stdlib` 生成的目录。",
);
const MODULES: Msg = Msg::new("modules", "模块");
const MODULE_COLUMN: Msg = Msg::new("module", "模块");
const SUMMARY_COLUMN: Msg = Msg::new("summary", "简介");
const ITEMS_COLUMN: Msg = Msg::new("items", "条目");
const ALL_MODULES: Msg = Msg::new("← all modules", "← 全部模块");
const EXAMPLES: Msg = Msg::new("examples", "示例");
const NO_ITEMS: Msg = Msg::new(
    "This module has no documented items yet.",
    "该模块尚无已记录的条目。",
);

/// Renders `/stdlib`.
#[must_use]
pub fn stdlib_index(
    book: &StdlibBook,
    lang: Lang,
    viewer: Option<&Viewer>,
) -> String {
    if book.modules.is_empty() {
        return layout::page(
            lang,
            TITLE.of(lang),
            "/stdlib",
            viewer,
            view! {
                <section class="empty-page">
                    <h1>{TITLE.of(lang)}</h1>
                    <p>{NO_STDLIB.of(lang)}</p>
                </section>
            },
        );
    }

    let module_count = thousands(i64::try_from(book.modules.len()).unwrap_or(0));
    let item_count = thousands(i64::try_from(book.total_items()).unwrap_or(0));
    let version = (!book.version.is_empty()).then(|| {
        let ver = book.version.clone();
        view! { <code>{ver}</code> }.into_any()
    });

    let rows: Vec<AnyView> = book
        .modules
        .iter()
        .map(|module| {
            let href = format!("/stdlib/{}?lang={}", module.slug, lang.code());
            let name = module.name.clone();
            let summary = module.summary.clone().unwrap_or_default();
            let count = thousands(i64::try_from(module.items.len()).unwrap_or(0));
            view! {
                <tr>
                    <td><a href=href>{name}</a></td>
                    <td class="muted">{summary}</td>
                    <td class="num">{count}</td>
                </tr>
            }
            .into_any()
        })
        .collect();

    layout::page(
        lang,
        TITLE.of(lang),
        "/stdlib",
        viewer,
        view! {
            <section class="page-head">
                <h1>{TITLE.of(lang)}</h1>
                <p>{LEDE.of(lang)}</p>
                <p class="small muted">
                    {version}
                    {if book.version.is_empty() { "" } else { " · " }}
                    {format!("{module_count} {} · {item_count} {}", MODULES.of(lang), ITEMS_COLUMN.of(lang))}
                </p>
            </section>
            <table class="data-table">
                <thead>
                    <tr>
                        <th>{MODULE_COLUMN.of(lang)}</th>
                        <th>{SUMMARY_COLUMN.of(lang)}</th>
                        <th class="num">{ITEMS_COLUMN.of(lang)}</th>
                    </tr>
                </thead>
                <tbody>{rows}</tbody>
            </table>
        },
    )
}

/// Renders `/stdlib/{module}`.
#[must_use]
pub fn stdlib_module(
    book: &StdlibBook,
    module: &StdlibModule,
    lang: Lang,
    viewer: Option<&Viewer>,
) -> String {
    let sidebar_links: Vec<_> = book
        .modules
        .iter()
        .map(|entry| {
            let current = (entry.slug == module.slug).then_some("page");
            let href = format!("/stdlib/{}?lang={}", entry.slug, lang.code());
            view! {
                <li>
                    <a href=href aria-current=current>{entry.name.as_str()}</a>
                </li>
            }
        })
        .collect();

    let summary_view = module
        .summary
        .as_deref()
        .filter(|_| module.html.is_empty())
        .map(|summary| view! { <p class="lede">{summary}</p> });

    let prose_view = (!module.html.is_empty()).then(|| {
        view! { <div class="markdown" inner_html=module.html.as_str()></div> }
    });

    let items_view = if module.items.is_empty() {
        Either::Left(if module.html.is_empty() {
            Either::Left(view! { <p class="muted">{NO_ITEMS.of(lang)}</p> })
        } else {
            Either::Right(view! { <div></div> })
        })
    } else {
        let cards: Vec<_> = module
            .items
            .iter()
            .map(|item| render_item(lang, item))
            .collect();
        Either::Right(view! { <div class="stdlib-items">{cards}</div> })
    };

    let page_title = format!("{} · {}", module.name, TITLE.of(lang));

    layout::page(
        lang,
        &page_title,
        "/stdlib",
        viewer,
        view! {
            <div class="docs-layout">
                <aside class="docs-side">
                    <p><a href=format!("/stdlib?lang={}", lang.code())>{ALL_MODULES.of(lang)}</a></p>
                    <h2>{MODULES.of(lang)}</h2>
                    <ul>{sidebar_links}</ul>
                </aside>
                <article class="docs-body">
                    <header class="page-head">
                        <h1>{module.name.as_str()}</h1>
                        {summary_view}
                    </header>
                    {prose_view}
                    {items_view}
                </article>
            </div>
        },
    )
}

#[allow(
    clippy::single_call_fn,
    reason = "each standard-library item groups its signature, documentation and examples"
)]
fn render_item(
    lang: Lang,
    item: &StdlibItem,
) -> impl RenderHtml {
    let kind = (!item.kind.is_empty()).then(|| {
        view! { <span class="stdlib-kind">{item.kind.as_str()}</span> }
    });
    let name = item.name.as_str();
    let sig = (!item.signature.is_empty()).then(|| {
        view! { <pre class="stdlib-sig"><code>{item.signature.as_str()}</code></pre> }
    });
    let doc = (!item.doc_html.is_empty()).then(|| {
        view! { <div class="markdown" inner_html=item.doc_html.as_str()></div> }
    });
    let examples = (!item.examples.is_empty()).then(|| {
        let blocks: Vec<_> = item
            .examples
            .iter()
            .map(|ex| view! { <pre class="code"><code>{ex.as_str()}</code></pre> })
            .collect();
        view! {
            <div class="stdlib-examples">
                <h4>{EXAMPLES.of(lang)}</h4>
                {blocks}
            </div>
        }
    });

    view! {
        <section class="stdlib-item" id=name>
            <div class="stdlib-item-head">
                {kind}
                <h3>{name}</h3>
            </div>
            {sig}
            {doc}
            {examples}
        </section>
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_book() -> StdlibBook {
        StdlibBook {
            version: "0.1.0".to_string(),
            modules: vec![StdlibModule {
                name: "Prelude".to_string(),
                slug: "Prelude".to_string(),
                summary: Some("Core functions and operators.".to_string()),
                html: String::new(),
                items: vec![StdlibItem {
                    kind: "fn".to_string(),
                    name: "sqrt".to_string(),
                    signature: "fn sqrt(x: Real[D]): Real[D^(1/2)]".to_string(),
                    doc: Some("Square root with half-dimension.".to_string()),
                    doc_html: "<p>Square root with half-dimension.</p>".to_string(),
                    examples: vec!["sqrt(4 m^2) == 2 m".to_string()],
                }],
            }],
        }
    }

    #[test]
    fn empty_stdlib_shows_mount_notice() {
        let html = stdlib_index(&StdlibBook::default(), Lang::En, None);
        assert!(html.contains("AEVIA_STDLIB_DOCS_DIR"));
    }

    #[test]
    fn stdlib_index_and_module_render_items() {
        let book = sample_book();
        let index_html = stdlib_index(&book, Lang::En, None);
        assert!(index_html.contains("/stdlib/Prelude"));
        assert!(index_html.contains("Core functions and operators."));

        let mod_html = stdlib_module(&book, &book.modules[0], Lang::En, None);
        assert!(mod_html.contains("fn sqrt(x: Real[D]): Real[D^(1/2)]"));
        assert!(mod_html.contains("Square root with half-dimension."));
        assert!(mod_html.contains("sqrt(4 m^2) == 2 m"));
    }

    #[test]
    fn stdlib_module_escapes_text_and_preserves_rendered_prose_in_both_languages() {
        let mut book = sample_book();
        let first = &mut book.modules[0];
        first.name = "Core & units".to_string();
        first.html = "<p>Module <em>prose</em></p>".to_string();
        first.items[0].name = "less< & \"".to_string();
        first.items[0].signature = "x < 2 & true".to_string();
        first.items[0].doc_html = "<p>Item <em>prose</em></p>".to_string();
        first.items[0].examples = vec!["x < 3 && true".to_string()];
        book.modules.push(StdlibModule {
            name: "Later module".to_string(),
            slug: "Later".to_string(),
            ..Default::default()
        });
        for (lang, examples) in [(Lang::En, "examples"), (Lang::Zh, "示例")] {
            let html = stdlib_module(&book, &book.modules[0], lang, None);
            let current = format!(
                "href=\"/stdlib/Prelude?lang={}\" aria-current=\"page\"",
                lang.code()
            );
            let later = format!("href=\"/stdlib/Later?lang={}\"", lang.code());
            assert!(html.find(&current).unwrap() < html.find(&later).unwrap());
            assert!(html.contains("Core &amp; units"));
            assert!(html.contains("id=\"less&lt; &amp; &quot;\""));
            assert!(html.contains("x &lt; 2 &amp; true"));
            assert!(html.contains("x &lt; 3 &amp;&amp; true"));
            assert!(html.contains(&format!("<h4>{examples}</h4>")));
            assert!(html.contains("<p>Module <em>prose</em></p>"));
            assert!(html.contains("<p>Item <em>prose</em></p>"));
            assert!(!html.contains("Core functions and operators."));
        }
    }

    #[test]
    fn empty_standalone_module_uses_the_summary_and_empty_notice() {
        let mut module = StdlibModule {
            name: "Empty module".to_string(),
            slug: "Empty".to_string(),
            summary: Some("Summary & details.".to_string()),
            ..Default::default()
        };
        let book = StdlibBook::default();
        let summary = stdlib_module(&book, &module, Lang::En, None);
        assert!(summary.contains("Summary &amp; details."));
        assert!(summary.contains(NO_ITEMS.of(Lang::En)));
        module.html = "<p>Overview only.</p>".to_string();
        let prose = stdlib_module(&book, &module, Lang::Zh, None);
        assert!(prose.contains("<p>Overview only.</p>"));
        assert!(!prose.contains(NO_ITEMS.of(Lang::Zh)));
        assert!(!prose.contains("Summary &amp; details."));
    }
}
